 const pair=`<div class="ref-cut-property-pair"><label>${esc(copy.position)}<input type="number" min="0" step="${1/studioNativeConfig.production.fps}" value="${clip.start}" data-native-clip-field="start" aria-label="${esc(copy.position)}"></label><label>${esc(copy.duration)}<input type="number" min="${1/studioNativeConfig.production.fps}" step="${1/studioNativeConfig.production.fps}" value="${clip.duration}" data-native-clip-field="duration" aria-label="${esc(copy.duration)}"></label></div>`;
