const studioEditStop=referenceCutStop;
referenceCutStop=function(){document.querySelector('[data-native-cut-preview]')?.studioPlayback?.pause();studioEditStop();};
/** Retain image drafts on visual tracks; static images have no decoding clock. */
function studioEditUpdateStills(surface,editor,time,ready=true){
 const clips=studioEditVisible(editor,time).filter(clip=>clip.kind==='image'),visible=new Set(clips.map(clip=>clip.id)),layer=surface.querySelector('.native-edit-media');
 if(ready)for(const element of layer.querySelectorAll('[data-native-edit-still]'))if(!visible.has(element.dataset.nativeEditStill))element.remove();
 for(const clip of clips){
  let element=[...layer.querySelectorAll('[data-native-edit-still]')].find(item=>item.dataset.nativeEditStill===clip.id);
  if(!element){element=document.createElement('div');element.dataset.nativeEditStill=clip.id;layer.append(element);}
  const rect=clip.nativeTransform||{x:0,y:0,width:1,height:1},media=studioCutClipMedia(clip);
  element.className='native-edit-layer ref-cut-still still frame'+(clip.frame||0);
  Object.assign(element.style,{left:rect.x*100+'%',top:rect.y*100+'%',width:rect.width*100+'%',height:rect.height*100+'%',opacity:clip.opacity/100,zIndex:String(editor.nativeTracks.findIndex(row=>row.id===clip.track)+1),transform:`translate(${clip.x/10}px,${clip.y/10}px) scale(${clip.scale/100}) rotate(${clip.rotation}deg)`});
  if(media?.url)element.style.backgroundImage=`url(${JSON.stringify(media.url)})`;
 }
}
